function [err, timepoints, species_out, observables_out] = bng_model(timepoints, species_init, parameters, suppress_plot)
%% bng_model - MATLAB ODE model
%% Generated by BioNetGen C++
%%
%% Usage:
%%   [err, timepoints, species_out, observables_out] = bng_model()
%%   [err, timepoints, species_out, observables_out] = bng_model(timepoints, species_init, parameters)

%% Default parameters, initial conditions, and calculation handlers
if (nargin < 1)
    timepoints = linspace(0.5, 2, 5)';
end
if (nargin < 2)
    species_init = getInitialSpecies();
end
if (nargin < 3)
    parameters = getDefaultParameters();
end
if (nargin < 4)
    suppress_plot = 0;
end

%% Validate input dimensions
if (length(parameters) ~= 4)
    error('parameters must have 4 elements');
end
if (length(species_init) ~= 2)
    error('species_init must have 2 elements');
end

%% Model dimensions
n_species = 2;
n_observables = 2;
n_ratelaws = 1;

%% ODE solver options
odeopts = odeset('RelTol', 1e-08, 'AbsTol', 1e-09, 'Stats', 'off', 'BDF', 'off', 'MaxOrder', 5);

%% Solve ODE
try
    [~, species_out] = ode15s(@(t,y) calc_species_deriv(t, y, parameters), timepoints, species_init, odeopts);
catch e
    err = 1;
    fprintf('Integration error: %s\n', e.message);
    timepoints = [];
    species_out = [];
    observables_out = [];
    return;
end

%% Compute observables at each time point
observables_out = zeros(length(timepoints), n_observables);
for t_idx = 1:length(timepoints)
    observables_out(t_idx, :) = calc_observables(species_out(t_idx, :)', parameters);
end

%% Plot results
if (~suppress_plot)
    figure;
    plot(timepoints, observables_out);
    legend('A', 'B', 'Location', 'best');
    ylabel('Number', 'FontSize', 12);
    xlabel('Time', 'FontSize', 12);
    title('', 'FontSize', 14);
end

err = 0;
return;

%% Default parameters
function p = getDefaultParameters()
    p = zeros(4, 1);
    p(1) = 0.4; % k
    p(2) = 0.2; % kr
    p(3) = 20; % N
    p(4) = 1; % V
end

%% Default initial species concentrations
function y0 = getInitialSpecies()
    y0 = zeros(2, 1);
    y0(1) = 20; % A()
    y0(2) = 0; % B()
end

%% Calculate expressions from parameters
function expressions = calc_expressions(parameters)
    expressions = zeros(4, 1);
    expressions(1) = parameters(1); % k
    expressions(2) = parameters(2); % kr
    expressions(3) = parameters(3); % N
    expressions(4) = parameters(4); % V
end

%% Calculate observables from species
function observables = calc_observables(species, parameters)
    observables = zeros(2, 1);
    observables(1) = species(1); % A
    observables(2) = species(2); % B
end

%% Calculate rate laws
function ratelaws = calc_ratelaws(species, expressions, observables)
    ratelaws = zeros(1, 1);
    ratelaws(1) = rate()*species(1);
end

%% Species derivative function
function Dspecies = calc_species_deriv(t, species, parameters)
    expressions = calc_expressions(parameters);
    observables = calc_observables(species, parameters);
    ratelaws = calc_ratelaws(species, expressions, observables);

    Dspecies = zeros(2, 1);

    Dspecies(1) = -ratelaws(1);
    Dspecies(2) = ratelaws(1);
end

end % main function
